/**
 * WeaponAssetLoader — 异步 GLB 武器资产加载器
 *
 * 特性：
 *  · URL 键控内存缓存（同一 URL 只发起一次网络请求）
 *  · 可配置超时（默认 8 s），超时后抛出 Error
 *  · 自动为所有 Mesh 设置 layer=1 + renderOrder=999 + depthTest=false
 *    （与程序化武器保持一致，避免深度冲突）
 *  · 提取约定命名挂点（muzzle_flash、hand_l）
 *  · AnimationMixer 自动创建（仅当 GLTF 包含动画时）
 */
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import type { GLTF } from 'three/examples/jsm/loaders/GLTFLoader.js';

export interface WeaponAsset {
  /** GLB 场景根节点（已配置渲染属性） */
  readonly group: THREE.Group;
  /** 已配置好的 AnimationMixer；GLTF 无动画时为 null */
  readonly mixer: THREE.AnimationMixer | null;
  /** 动画名 → AnimationClip 只读映射 */
  readonly clips: ReadonlyMap<string, THREE.AnimationClip>;
  /** 枪口火焰挂点（约定命名："muzzle_flash" 或 "Muzzle"），不存在时 null */
  readonly muzzleBone: THREE.Object3D | null;
  /** 左手 IK 目标（约定命名："hand_l" 或 "LeftHand"），不存在时 null */
  readonly leftHandBone: THREE.Object3D | null;
}

export class WeaponAssetLoader {
  private static readonly _cache = new Map<string, WeaponAsset>();
  private static _loader: GLTFLoader | null = null;

  /** 懒初始化 loader（方便测试时 mock 注入）。 */
  static setLoader(loader: GLTFLoader): void {
    this._loader = loader;
  }

  private static _getLoader(): GLTFLoader {
    if (!this._loader) this._loader = new GLTFLoader();
    return this._loader;
  }

  /**
   * 异步加载 GLB 武器资产。
   * 同一 URL 二次调用直接返回缓存，无额外网络开销。
   *
   * @throws 超时或网络/解析错误时抛出 Error
   */
  static async load(url: string, timeoutMs = 8_000): Promise<WeaponAsset> {
    const cached = this._cache.get(url);
    if (cached) return cached;

    const loader = this._getLoader();
    const gltf = await Promise.race<GLTF>([
      new Promise<GLTF>((resolve, reject) =>
        loader.load(
          url,
          resolve,
          undefined,
          (err) => reject(err instanceof Error ? err : new Error(String(err))),
        ),
      ),
      new Promise<never>((_, reject) =>
        setTimeout(
          () => reject(new Error(`WeaponAssetLoader: timeout loading "${url}" after ${timeoutMs}ms`)),
          timeoutMs,
        ),
      ),
    ]);

    const asset = this._processGLTF(gltf);
    this._cache.set(url, asset);
    return asset;
  }

  /** 清空缓存（场景重建 / 热重载时使用）。 */
  static clearCache(): void {
    this._cache.clear();
  }

  /** 当前缓存条目数（供测试与调试使用）。 */
  static get cacheSize(): number {
    return this._cache.size;
  }

  private static _processGLTF(gltf: GLTF): WeaponAsset {
    const group = gltf.scene;

    // 统一设置渲染属性，与程序化武器行为一致
    group.traverse((obj) => {
      obj.layers.set(1);
      const mesh = obj as THREE.Mesh;
      if (!mesh.isMesh) return;
      mesh.renderOrder = 999;
      const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      for (const mat of mats) {
        (mat as THREE.Material).depthTest = false;
      }
    });

    // AnimationMixer：仅当 GLTF 内含动画时创建
    const mixer = gltf.animations.length > 0 ? new THREE.AnimationMixer(group) : null;

    const clips = new Map<string, THREE.AnimationClip>();
    for (const clip of gltf.animations) {
      clips.set(clip.name, clip);
    }

    // 约定命名挂点查找（顺序优先）
    const muzzleBone =
      group.getObjectByName('muzzle_flash') ??
      group.getObjectByName('Muzzle') ??
      null;
    const leftHandBone =
      group.getObjectByName('hand_l') ??
      group.getObjectByName('LeftHand') ??
      null;

    return { group, mixer, clips, muzzleBone, leftHandBone };
  }
}
